'use client';

import * as React from 'react';

export interface BalinaIconProps extends React.SVGProps<SVGSVGElement> {
  size?: number;
}

function Stroke({
  size = 16,
  children,
  ...rest
}: BalinaIconProps & { children: React.ReactNode }) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 16 16"
      role="img"
      aria-hidden="true"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.25}
      {...rest}
    >
      {children}
    </svg>
  );
}

function Fill({
  size = 16,
  children,
  ...rest
}: BalinaIconProps & { children: React.ReactNode }) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 16 16"
      role="img"
      aria-hidden="true"
      fill="currentColor"
      {...rest}
    >
      {children}
    </svg>
  );
}

