/* ----- 20×20 viewBox stroke ikonları ----- */
function Stroke20({
  size = 16,
  children,
  ...rest
}: BalinaIconProps & { children: React.ReactNode }) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="2 2 16 16"
      role="img"
      aria-hidden="true"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.25}
      strokeLinecap="round"
      strokeLinejoin="round"
      {...rest}
    >
      {children}
    </svg>
  );
}

function Fill20({
  size = 16,
  children,
  ...rest
}: BalinaIconProps & { children: React.ReactNode }) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 20 20"
      role="img"
      aria-hidden="true"
      fill="currentColor"
      {...rest}
    >
      {children}
    </svg>
  );
}

